H_{\rm inf} = \sum_{k} \big[ \chi_k^{\dagger} H_{\rm local} \chi_k+ (e^{ik}\chi_k^{\dagger} H_{\rm hop} \chi_{k}+ {\rm h.c}) \\
+ \chi_k^{\dagger} H_{\rm pair}^{(l^\prime)} \chi_{k} + {\rm h.c.}) \big]
\end{aligned}
\label{C5}

$H_{\rm pair}^{(l^\prime)} = 
\begin{pmatrix}
C_{0,0} & C_{0,1} & C_{0,2} & \cdots & C_{0,f_n-1} \\
C_{1,0} & C_{1,1} & C_{1,2} & \cdots & C_{1,f_n-1} \\
